var bodies = window.AGENTS_VISUALIZATION.data.bodies;
var canvas = document.getElementById("orbits");
var context = canvas.getContext("2d");
var stars = [];
for (var starIndex = 0; starIndex < 140; starIndex++) stars.push({ x: Math.random(), y: Math.random(), size: Math.random() * 1.2 + 0.2 });
document.getElementById("count-badge").textContent = bodies.length + " Planeten";
var state = { time: 0, yaw: 0.35, tilt: 53 * Math.PI / 180, zoom: 1, speed: 1, running: true, last: 0 };
var resize = function () {
  var ratio = window.devicePixelRatio || 1;
  canvas.width = canvas.clientWidth * ratio;
  canvas.height = canvas.clientHeight * ratio;
  context.setTransform(ratio, 0, 0, ratio, 0, 0);
};
var project = function (x, z) {
  var width = canvas.clientWidth, height = canvas.clientHeight;
  var scale = Math.min(width / 520, height / 470) * state.zoom;
  var xr = x * Math.cos(state.yaw) - z * Math.sin(state.yaw);
  var zr = x * Math.sin(state.yaw) + z * Math.cos(state.yaw);
  var yr = -zr * Math.sin(state.tilt);
  var depth = zr * Math.cos(state.tilt);
  var perspective = 900 / (900 + depth * 0.45);
  return { x: width / 2 + xr * scale * perspective, y: height / 2 + yr * scale * perspective, depth: depth, k: perspective * scale };
};
var drawOrbit = function (radius) {
  context.beginPath();
  for (var step = 0; step <= 160; step++) {
    var angle = step / 160 * Math.PI * 2;
    var point = project(radius * Math.cos(angle), radius * Math.sin(angle));
    if (step === 0) context.moveTo(point.x, point.y); else context.lineTo(point.x, point.y);
  }
  context.strokeStyle = "rgba(124,152,203,.29)";
  context.lineWidth = 1;
  context.stroke();
};
var drawBody = function (body) {
  var radius = Math.max(2, body.size * body.point.k);
  var shade = context.createRadialGradient(body.point.x - radius * 0.4, body.point.y - radius * 0.4, 0.5, body.point.x, body.point.y, radius * 1.3);
  shade.addColorStop(0, "#ffffff");
  shade.addColorStop(0.23, body.color);
  shade.addColorStop(1, "#172239");
  context.fillStyle = shade;
  context.beginPath();
  context.arc(body.point.x, body.point.y, radius, 0, Math.PI * 2);
  context.fill();
  if (body.rings) {
    context.beginPath();
    context.ellipse(body.point.x, body.point.y, radius * 1.8, radius * 0.52, -0.28, 0, Math.PI * 2);
    context.strokeStyle = "rgba(235,210,160,.75)";
    context.lineWidth = 2;
    context.stroke();
  }
  context.font = "12px system-ui, sans-serif";
  context.textAlign = "center";
  context.fillStyle = "#cbd8f2";
  context.fillText(body.name, body.point.x, body.point.y + radius + 15);
};
var draw = function (now) {
  if (!state.last) state.last = now;
  if (state.running) state.time += (now - state.last) / 1000 * state.speed;
  state.last = now;
  var width = canvas.clientWidth, height = canvas.clientHeight;
  context.clearRect(0, 0, width, height);
  stars.forEach(function (star) { context.fillStyle = "rgba(203,216,242,.5)"; context.fillRect(star.x * width, star.y * height, star.size, star.size); });
  bodies.forEach(function (body) { drawOrbit(body.orbitRadius); });
  var sun = project(0, 0);
  var glow = context.createRadialGradient(sun.x, sun.y, 2, sun.x, sun.y, 34 * state.zoom);
  glow.addColorStop(0, "rgba(255,220,140,1)");
  glow.addColorStop(0.35, "rgba(255,180,80,.55)");
  glow.addColorStop(1, "rgba(255,150,50,0)");
  context.fillStyle = glow;
  context.beginPath();
  context.arc(sun.x, sun.y, 34 * state.zoom, 0, Math.PI * 2);
  context.fill();
  var placed = bodies.map(function (body) {
    var angle = state.time * body.speed * 0.6 + body.phase;
    return { name: body.name, size: body.size, color: body.color, rings: body.rings, point: project(body.orbitRadius * Math.cos(angle), body.orbitRadius * Math.sin(angle)) };
  });
  placed.sort(function (first, second) { return second.point.depth - first.point.depth; }).forEach(drawBody);
  window.requestAnimationFrame(draw);
};
document.getElementById("speed").addEventListener("input", function (event) { state.speed = Number(event.target.value); });
document.getElementById("tilt").addEventListener("input", function (event) { state.tilt = Number(event.target.value) * Math.PI / 180; });
document.getElementById("zoom").addEventListener("input", function (event) { state.zoom = Number(event.target.value); });
var pauseButton = document.getElementById("pause");
pauseButton.addEventListener("click", function () { state.running = !state.running; pauseButton.textContent = state.running ? "Pause" : "Weiter"; });
var dragStartX = null;
canvas.addEventListener("pointerdown", function (event) { dragStartX = event.clientX; canvas.classList.add("dragging"); canvas.setPointerCapture(event.pointerId); });
canvas.addEventListener("pointermove", function (event) { if (dragStartX === null) return; state.yaw += (event.clientX - dragStartX) * 0.01; dragStartX = event.clientX; });
canvas.addEventListener("pointerup", function () { dragStartX = null; canvas.classList.remove("dragging"); });
window.addEventListener("resize", resize);
resize();
window.requestAnimationFrame(draw);

var rows = window.AGENTS_VISUALIZATION.data.rows;
var width = document.getElementById("chart").clientWidth, height = 220, margin = { top: 12, right: 12, bottom: 28, left: 36 };
var svg = d3.select("#chart").append("svg").attr("width", width).attr("height", height);
var x = d3.scaleBand().domain(rows.map(function (row) { return row.month; })).range([margin.left, width - margin.right]).padding(0.25);
var y = d3.scaleLinear().domain([0, d3.max(rows, function (row) { return row.reviews; })]).nice().range([height - margin.bottom, margin.top]);
svg.append("g").attr("transform", "translate(0," + (height - margin.bottom) + ")").call(d3.axisBottom(x));
svg.append("g").attr("transform", "translate(" + margin.left + ",0)").call(d3.axisLeft(y).ticks(4));
svg.selectAll("rect").data(rows).join("rect").attr("x", function (row) { return x(row.month); }).attr("width", x.bandwidth()).attr("y", function (row) { return y(row.reviews); }).attr("height", function (row) { return y(0) - y(row.reviews); }).attr("rx", 4).style("fill", "var(--agents-accent)");

